public static void trigger(ItemStack stack, LivingEntity bearer, DamageSource incoming) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        if (!(bearer.getWorld() instanceof ServerWorld world)
                || stack == null || !stack.isOf(ItemsRegistry.THE_DEVOURER.get())
                || !(incoming.getAttacker() instanceof LivingEntity attacker)
                || !attacker.isAlive() || attacker.isRemoved() || attacker.getWorld() != world
                || isInvulnerablePlayer(attacker)
                || attacker == bearer || !EntityPredicates.VALID_LIVING_ENTITY.test(attacker)
                || !HelperMethods.checkAbilityTarget(attacker, bearer)) {
            return;
        }
        double reach = Math.max(1.0, Config.uniqueEffects.devourer.reprisalReach);
        if (attacker.squaredDistanceTo(bearer) > reach * reach) {
            return;
        }
        if (!lockoutReady(world, bearer.getUuid())) {
            return;
        }

        UniqueAbilityExecution execution = UniqueAbilityApi.preparePassive(AbyssalSpectralMasteryAbilities.DEVOURER_REPRISAL,
                UniqueAbilityContext.passive(world, stack, bearer, attacker, null), builder -> builder
                        .set(AbyssalSpectralMasteryAbilities.TUNING, AbyssalSpectralMasteryTuning.EMPTY
                                .with(AbyssalSpectralMasteryTuning.Setting.REPRISAL_RADIUS, Config.uniqueEffects.devourer.reprisalRadius)
                                .with(AbyssalSpectralMasteryTuning.Setting.REPRISAL_TARGET_CAP, Config.uniqueEffects.devourer.reprisalTargetCap)
                                .with(AbyssalSpectralMasteryTuning.Setting.REPRISAL_PULL, Config.uniqueEffects.devourer.reprisalPullStrength)
                                .with(AbyssalSpectralMasteryTuning.Setting.REPRISAL_DAMAGE_MULTIPLIER, 1)));
        UniqueAbilityApi.start(execution);
        AbyssalSpectralMasteryTuning tuning = AbyssalSpectralMasteryAbilities.tuning(execution);

        int mode = tuning.integer(AbyssalSpectralMasteryTuning.Setting.MODE, 0);
        boolean guarding = (mode & 512) != 0;
        applyLockout(world, bearer.getUuid(),
                tuning.integer(AbyssalSpectralMasteryTuning.Setting.LOCKOUT_TICKS, 0));
        double radius = Math.max(0.5, tuning.get(AbyssalSpectralMasteryTuning.Setting.REPRISAL_RADIUS,
                Config.uniqueEffects.devourer.reprisalRadius));
        int targetCap = Math.max(1, tuning.integer(AbyssalSpectralMasteryTuning.Setting.REPRISAL_TARGET_CAP,
                Config.uniqueEffects.devourer.reprisalTargetCap));
        Vec3d center = resolveMawCenter(world, guarding ? bearer : attacker);
        boolean retrieval = (mode & 1024) != 0;
        int dragDuration = retrieval ? 40 : Math.max(1, Config.uniqueEffects.devourer.reprisalDragDuration);
        List<LivingEntity> targets = collectTargets(world, bearer, attacker, center, radius, targetCap);
        float damage = HelperMethods.abilityScaledDamage(SpellScalingProfile.SOUL, bearer, stack,
                Config.uniqueEffects.devourer.reprisalDamageScaling,
                Config.uniqueEffects.devourer.reprisalSpellScaling)
                * (float) tuning.get(AbyssalSpectralMasteryTuning.Setting.REPRISAL_DAMAGE_MULTIPLIER, 1);
        double secondary = tuning.get(AbyssalSpectralMasteryTuning.Setting.REPRISAL_SECONDARY_MULTIPLIER, 1);
        DevourerAbilityManager.ReprisalRedirect redirect = guarding ? null
                : DevourerAbilityManager.feedFromReprisal(world, bearer.getUuid(), center, attacker,
                        Math.max(10, dragDuration + 7),
                        tuning.get(AbyssalSpectralMasteryTuning.Setting.RANGE, 0));
        int hits = 0;
        for (LivingEntity target : targets) {
            float scaled = targetDamage(damage, target == attacker, secondary);
            if (damageTarget(world, bearer, stack, target, scaled)) {
                hits++;
                UniqueAbilityApi.emit(execution, net.sweenus.simplyswords.api.ability.UniqueAbilityPhase.HIT,
                        AbyssalSpectralMasteryAbilities.HIT, target, 1, scaled);
            }
            if (redirect != null && target.isAlive()) {
                DevourerAbilityManager.markRouted(world, bearer.getUuid(), target.getUuid(), dragDuration + 100,
                        tuning.get(AbyssalSpectralMasteryTuning.Setting.ROUTED_DAMAGE_BONUS, 0));
            }
            applyReprisalStatus(bearer, target == attacker ? attacker : null, tuning);
        }
        grantReprisalAbsorption(bearer, tuning, mode);
        if (guarding) applyGuardianBoon(bearer, tuning);
        Vec3d destination = redirect == null ? center : redirect.destination();
        UUID tendrilId = redirect == null ? null : redirect.tendrilId();
        DevourerReprisalVisualEntity visual = new DevourerReprisalVisualEntity(world, center,
                VISUAL_LIFETIME, (float) radius, redirect != null);
        world.spawnEntity(visual);
        spawnOpeningEffects(world, center, redirect != null);

        List<UUID> targetIds = targets.stream()
                .filter(LivingEntity::isAlive)
                .map(Entity::getUuid)
                .toList();
        long now = world.getTime();
        long dragEndTick = now + dragDuration;
        long cleanupTick = Math.max(dragEndTick, now + CLOSING_EFFECT_TICK + 1L);
        ActiveReprisal reprisal = new ActiveReprisal(bearer.getUuid(), center, destination,
                redirect != null, guarding, targetIds, dragEndTick, cleanupTick,
                now + CLOSING_EFFECT_TICK, retrieval ? dragEndTick : now + TENDRIL_RETRACT_TICK, tendrilId, execution,
                retrieval && redirect != null, redirect == null ? null : redirect.massVisualId(), hits);
        ACTIVE.computeIfAbsent(world, ignored -> new ArrayList<>()).add(reprisal);
        }
    }

public static boolean tryDeflectIncomingDamage(LivingEntity bearer, DamageSource source, float amount) {
        if (SUPPRESS_IMPLICITS.get() || bearer.getWorld().isClient() || !Config.general.enableWeaponImplicits
                || source.isIn(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }

        for (ItemStack stack : List.of(bearer.getMainHandStack(), bearer.getOffHandStack())) {
            Optional<WeaponImplicitComponent> component = getOrCreateWeaponImplicit(stack);
            if (component.isEmpty()) {
                continue;
            }
            WeaponImplicitDefinition definition = DEFINITIONS_BY_ID.get(component.get().implicitId());
            if (definition != null && definition.incomingDamageHandler() != null
                    && definition.incomingDamageHandler().shouldCancel(stack, component.get(), bearer, source, amount)) {
                return true;
            }
        }
        return false;
    }

private static boolean tryDeflect(ItemStack stack, WeaponImplicitComponent component, LivingEntity bearer, DamageSource source, float amount) {
        if (missedRoll(bearer, component.value())) {
            return false;
        }
        if (bearer.getWorld() instanceof ServerWorld serverWorld) {
            serverWorld.playSound(null, bearer.getBlockPos(), SoundRegistry.MAGIC_SWORD_PARRY_01.get(), SoundCategory.PLAYERS, 0.55F, 1.25F);
            serverWorld.spawnParticles(ParticleTypes.ENCHANTED_HIT, bearer.getX(), bearer.getBodyY(0.55), bearer.getZ(), 8, 0.35, 0.25, 0.35, 0.03);
            if (stack.isOf(ItemsRegistry.THE_DEVOURER.get())) {
                DevourerReprisalManager.trigger(stack, bearer, source);
            }
        }
        return true;
    }

public static void tick(ServerWorld world) {
        Map<UUID, Long> lockouts = LOCKOUTS.get(world);
        if (lockouts != null) {
            lockouts.values().removeIf(ready -> ready <= world.getTime());
            if (lockouts.isEmpty()) LOCKOUTS.remove(world);
        }
        List<ActiveReprisal> active = ACTIVE.get(world);
        if (active == null || active.isEmpty()) {
            return;
        }
        long now = world.getTime();
        Iterator<ActiveReprisal> iterator = active.iterator();
        while (iterator.hasNext()) {
            ActiveReprisal reprisal = iterator.next();
            LivingEntity bearer = resolveLiving(world, reprisal.bearerId);
            if (!reprisal.closingEffectsPlayed && now >= reprisal.closingEffectTick) {
                reprisal.closingEffectsPlayed = true;
                spawnClosingEffects(world, reprisal.mawCenter, reprisal.redirected);
            }
            if (!reprisal.tendrilRetracting && now >= reprisal.tendrilRetractTick) {
                reprisal.tendrilRetracting = true;
                beginTendrilRetraction(world, reprisal);
            }
            if (bearer != null && !reprisal.dragFinished && now < reprisal.dragEndTick) {
                tickPull(world, bearer, reprisal);
            }
            if (now >= reprisal.cleanupTick) {
                beginTendrilRetraction(world, reprisal);
                UniqueAbilityApi.finish(reprisal.execution, reprisal.execution.definition().id(),
                        reprisal.hits);
                iterator.remove();
            }
        }
        if (active.isEmpty()) {
            ACTIVE.remove(world);
        }
    }

private static List<LivingEntity> collectTargets(ServerWorld world, LivingEntity bearer,
                                                       LivingEntity attacker, Vec3d center,
                                                       double radius, int cap) {
        List<LivingEntity> targets = new ArrayList<>();
        targets.add(attacker);
        if (cap <= 1) {
            return targets;
        }
        Box search = new Box(center.x - radius, center.y - radius, center.z - radius,
                center.x + radius, center.y + radius, center.z + radius);
        world.getEntitiesByClass(LivingEntity.class, search,
                        target -> target != attacker && target != bearer && target.isAlive()
                                && !target.isRemoved() && !isInvulnerablePlayer(target)
                                && EntityPredicates.VALID_LIVING_ENTITY.test(target)
                                && HelperMethods.checkAbilityTarget(target, bearer)
                                && horizontalDistanceSquared(target.getPos(), center) <= radius * radius)
                .stream()
                .sorted(Comparator.comparingDouble(target -> target.squaredDistanceTo(center)))
                .limit(cap - 1L)
                .forEach(targets::add);
        return targets;
    }

private static void tickPull(ServerWorld world, LivingEntity bearer, ActiveReprisal reprisal) {
        AbyssalSpectralMasteryTuning tuning = AbyssalSpectralMasteryAbilities.tuning(reprisal.execution);
        double configured = Math.max(0.0, reprisal.pushing
                ? tuning.get(AbyssalSpectralMasteryTuning.Setting.REPRISAL_PUSH_STRENGTH, 0)
                : tuning.get(AbyssalSpectralMasteryTuning.Setting.REPRISAL_PULL,
                        Config.uniqueEffects.devourer.reprisalPullStrength));
        if (configured <= 0.0) return;
        Vec3d destination = reprisal.destination;
        if (reprisal.redirected && reprisal.massVisualId != null) {
            destination = DevourerAbilityManager.activeCenter(world, reprisal.bearerId, reprisal.massVisualId);
            if (destination == null) {
                reprisal.dragFinished = true;
                beginTendrilRetraction(world, reprisal);
                return;
            }
        }
        for (UUID targetId : reprisal.targetIds) {
            LivingEntity target = resolveLiving(world, targetId);
            if (target == null || isInvulnerablePlayer(target)
                    || !HelperMethods.checkAbilityTarget(target, bearer)) {
                continue;
            }
            Vec3d offset;
            if (reprisal.redirected) {
                Vec3d desiredBase = destination.subtract(0.0, target.getHeight() * 0.5, 0.0);
                offset = desiredBase.subtract(target.getPos());
            } else {
                offset = new Vec3d(destination.x - target.getX(), 0.0,
                        destination.z - target.getZ());
            }
            if (reprisal.pushing) {
                offset = offset.multiply(-1.0);
                if (offset.horizontalLengthSquared() < 1.0E-6) {
                    offset = Vec3d.fromPolar(0, bearer.getYaw());
                }
            }
            double distance = offset.length();
            if (reprisal.retrieval) {
                if (distance <= 0.34 + target.getWidth() * 0.18) {
                    reprisal.dragFinished = true;
                    beginTendrilRetraction(world, reprisal);
                    continue;
                }
                Vec3d before = target.getPos();
                Vec3d step = offset.normalize().multiply(Math.min(1.5, distance));
                target.move(MovementType.SELF, step);
                target.setVelocity(Vec3d.ZERO);
                target.velocityModified = true;
                target.fallDistance = 0;
                if (target.getPos().subtract(before).squaredDistanceTo(step) > 0.0025) {
                    reprisal.dragFinished = true;
                    beginTendrilRetraction(world, reprisal);
                }
                continue;
            }
            if (distance < 0.08) {
                continue;
            }
            double size = Math.max(1.0, Math.max(target.getWidth(), target.getHeight()));
            double resistance = MathHelper.clamp(
                    target.getAttributeValue(EntityAttributes.GENERIC_KNOCKBACK_RESISTANCE), 0.0, 1.0);
            double response = MathHelper.clamp(1.0 / (size * (1.0 + resistance * 2.0)), 0.12, 1.0);
            double strength = Math.min(0.48, configured * response * Math.min(1.5, 0.9 + distance * 0.08));
            Vec3d pull = offset.normalize().multiply(strength);
            Vec3d current = target.getVelocity().multiply(0.52);
            target.setVelocity(current.x + pull.x,
                    MathHelper.clamp(current.y + pull.y, -0.32, 0.38),
                    current.z + pull.z);
            target.velocityModified = true;
            target.fallDistance = 0.0F;
        }
    }

private static boolean lockoutReady(ServerWorld world, UUID bearerId) {
        Map<UUID, Long> lockouts = LOCKOUTS.get(world);
        Long ready = lockouts == null ? null : lockouts.get(bearerId);
        return ready == null || world.getTime() >= ready;
    }

private static void applyLockout(ServerWorld world, UUID bearerId, int lockoutTicks) {
        if (lockoutTicks <= 0) return;
        Map<UUID, Long> lockouts = LOCKOUTS.computeIfAbsent(world, ignored -> new HashMap<>());
        long now = world.getTime();
        lockouts.values().removeIf(ready -> ready < now);
        lockouts.put(bearerId, now + lockoutTicks);
    }

private static boolean damageTarget(ServerWorld world, LivingEntity bearer, ItemStack stack,
                                     LivingEntity target, float baseDamage) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        if (baseDamage <= 0.0F || !target.isAlive()) {
            return false;
        }
        DamageSource magic = bearer.getDamageSources().magic();
        DamageSource source = new DamageSource(magic.getTypeRegistryEntry(), bearer, bearer);
        float damage = HelperMethods.applyAbilityDamageEnchantments(world, stack, target, source, baseDamage);
        boolean[] damaged = {false};
        WeaponImplicitRegistry.runSuppressed(() -> damaged[0] = HelperMethods.damageThroughIframes(target, source, damage));
        return damaged[0];
        }
    }

private static LivingEntity resolveLiving(ServerWorld world, UUID id) {
        Entity entity = id == null ? null : world.getEntity(id);
        return entity instanceof LivingEntity living && living.isAlive() && !living.isRemoved() ? living : null;
    }

private static void beginTendrilRetraction(ServerWorld world, ActiveReprisal reprisal) {
        if (reprisal.tendrilId == null) {
            return;
        }
        Entity entity = world.getEntity(reprisal.tendrilId);
        if (entity instanceof DevourerTendrilVisualEntity tendril && tendril.getRetractAge() < 0) {
            Entity target = tendril.getTarget();
            tendril.beginRetraction(target == null ? tendril.getStoredEnd() : target.getPos());
        }
    }

public static void clear(ServerWorld world) {
        if (world == null) return;
        List<ActiveReprisal> active = ACTIVE.remove(world);
        if (active != null) active.forEach(reprisal -> UniqueAbilityApi.cancel(reprisal.execution));
        LOCKOUTS.remove(world);
    }

public static void clearAll() {
        ACTIVE.values().forEach(active -> active.forEach(
                reprisal -> UniqueAbilityApi.cancel(reprisal.execution)));
        ACTIVE.clear();
        LOCKOUTS.clear();
    }

public static void tryTriggerChainLightning(ItemStack stack, LivingEntity target, ServerPlayerEntity player) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        if (SUPPRESS_CHAIN.get() || stack == null || stack.isEmpty() || target == null || player == null
                || !stack.isOf(ItemsRegistry.STORMBRINGER.get()) || !AwakeningApi.isAbilityUnlocked(stack)) return;
        ServerWorld world = player.getServerWorld();
        long now = world.getTime();
        OwnerState state = ownerState(player);
        if (state.lastAttemptTick == now) return;
        state.lastAttemptTick = now;
        if (now < state.nextChainTick) return;

        UniqueAbilityExecution execution = StormFrostWaterMasteryCombatManager.beginPassive(
                StormFrostWaterMasteryAbilities.STORMBRINGER_CHAIN, world, stack, player, target);
        StormFrostWaterMasteryTuning tuning = StormFrostWaterMasteryAbilities.tuning(execution);
        observeTuning(player, tuning);
        try {
            int chargeCap = chargeCap(tuning);
            ParryComponent component = normalizeCharges(stack, chargeCap);
            int stormCharges = component.stormCharges();
            if (stormCharges <= 0) return;

            float baseDamage = HelperMethods.abilityScaledDamage("lightning", player, stack,
                    Config.uniqueEffects.stormbringer.chainLightningDamageScaling,
                    Config.uniqueEffects.stormbringer.chainLightningSpellScaling);
            baseDamage *= (float) value(tuning, s("STORMBRINGER_CHAIN_DAMAGE_MULTIPLIER"),
                    s("DAMAGE_MULTIPLIER"), 1);
            boolean fullBattery = tuning.flag(1 << 15) && stormCharges >= chargeCap;
            if (fullBattery) {
                baseDamage *= (float) value(tuning, s("STORMBRINGER_FULL_DAMAGE_MULTIPLIER"), null, 1.25);
            }
            if (tuning.flag(1 << 16)) {
                baseDamage *= (float) supercellMultiplier(stormCharges, value(tuning,
                        s("STORMBRINGER_SUPERCELL_DAMAGE_PER_CHARGE"), s("PER_STACK_MULTIPLIER"), .04));
            }

            boolean focused = tuning.flag(1 << 25);
            boolean rolling = tuning.flag(1 << 26);
            int activeTargetCap = rolling
                    ? integer(tuning, s("STORMBRINGER_ROLLING_TARGET_CAP"), s("TARGET_CAP"), 10)
                    : tuning.has(s("TARGET_CAP")) ? tuning.integer(s("TARGET_CAP"), MAX_CHAIN_TARGETS)
                    : MAX_CHAIN_TARGETS;
            int targetCount = chainTargetCount(stormCharges,
                    activeTargetCap,
                    focused ? 0 : integer(tuning, s("STORMBRINGER_FORK_EXTRA_TARGETS"), null, 0), focused);
            double range = value(tuning, s("STORMBRINGER_CHAIN_RANGE"), s("RANGE"),
                    Config.uniqueEffects.stormbringer.chainLightningRange);
            if (rolling) {
                range += value(tuning, s("STORMBRINGER_ROLLING_RANGE_BONUS"), null, 3);
            }
            List<LivingEntity> chain = ChainLightningVisualManager.chainTargets(world, player, target,
                    targetCount, range, Math.max(1, Config.uniqueEffects.stormbringer.chainSearchCap));
            if (chain.isEmpty()) return;

            Set<UUID> damaged = new HashSet<>();
            Set<UUID> killed = new HashSet<>();
            List<LivingEntity> visualHits = new ArrayList<>();
            SUPPRESS_CHAIN.set(true);
            if (focused) {
                LivingEntity primary = chain.getFirst();
                boolean preMarked = isMarked(world, player, primary);
                int hitCount = integer(tuning, s("STORMBRINGER_FOCUSED_HIT_COUNT"), s("COUNT"), 3);
                float hitDamage = baseDamage * (float) value(tuning,
                        s("STORMBRINGER_FOCUSED_HIT_DAMAGE_MULTIPLIER"), s("SECONDARY_DAMAGE_MULTIPLIER"), .55);
                if (preMarked) hitDamage *= (float) value(tuning,
                        s("STORMBRINGER_MARK_DAMAGE_MULTIPLIER"), s("OUTGOING_MULTIPLIER"), 1.15);
                for (int hit = 0; hit < hitCount && primary.isAlive(); hit++) {
                    if (damage(world, player, stack, primary, hitDamage, killed)) {
                        damaged.add(primary.getUuid());
                    }
                }
                if (damaged.contains(primary.getUuid())) {
                    visualHits.add(primary);
                    applyMark(world, player, primary, tuning);
                }
            } else {
                double rollingFactor = rolling ? value(tuning,
                        s("STORMBRINGER_ROLLING_JUMP_MULTIPLIER"), s("PER_STACK_MULTIPLIER"), .82) : 1;
                for (int index = 0; index < chain.size(); index++) {
                    LivingEntity chainTarget = chain.get(index);
                    float hitDamage = baseDamage * (float) rollingMultiplier(index, rollingFactor);
                    if (isMarked(world, player, chainTarget)) {
                        hitDamage *= (float) value(tuning,
                                s("STORMBRINGER_MARK_DAMAGE_MULTIPLIER"), s("OUTGOING_MULTIPLIER"), 1.15);
                    }
                    if (damage(world, player, stack, chainTarget, hitDamage, killed)) {
                        damaged.add(chainTarget.getUuid());
                        visualHits.add(chainTarget);
                        applyMark(world, player, chainTarget, tuning);
                    }
                }
                if (tuning.flag(1 << 22) && !chain.isEmpty()
                        && damaged.contains(chain.getLast().getUuid())) {
                    damageGroundCurrent(world, player, stack, chain, baseDamage, tuning, damaged, killed);
                }
            }
            SUPPRESS_CHAIN.set(false);
            if (damaged.isEmpty()) return;
            ChainLightningVisualManager.spawnStormbringerChainEffects(world, player, visualHits);

            boolean free = tuning.flag(1 << 10) && !fullBattery && now >= state.nextFreeChainTick;
            int consumed = resolvedChargeCost(fullBattery, free, stormCharges,
                    integer(tuning, s("STORMBRINGER_FULL_CHARGE_COST"), s("COUNT"), 2));
            if (free) {
                state.nextFreeChainTick = now + integer(tuning,
                        s("STORMBRINGER_FREE_CHAIN_LOCKOUT_TICKS"), s("LOCKOUT_TICKS"), 80);
            }
            ParryComponent updated = component;
            for (int i = 0; i < consumed; i++) updated = updated.consumeStormCharge();
            if (tuning.flag(1 << 23) && !killed.isEmpty()) {
                int refund = boundedKillRefund(killed.size(), integer(tuning,
                        s("STORMBRINGER_KILL_REFUND_CAP"), s("COUNT"), 2));
                updated = updated.gainBlockedStormCharges(refund, chargeCap);
            }
            stack.set(ComponentTypeRegistry.PARRY.get(), updated);

            if (consumed > 0 && tuning.flag(1 << 13) && damaged.contains(target.getUuid())) {
                target.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,
                        integer(tuning, s("STORMBRINGER_RESIDUAL_SLOW_TICKS"),
                                s("STATUS_DURATION_TICKS"), 30), 0), player);
            }
            if (consumed > 0 && tuning.flag(1 << 14)) recordSpentCharges(player, tuning, consumed);

            int cooldown = tuning.has(s("STORMBRINGER_CHAIN_COOLDOWN_MULTIPLIER"))
                    ? Math.max(1, Math.round(Config.uniqueEffects.stormbringer.chainLightningCooldown
                    * (float) tuning.get(s("STORMBRINGER_CHAIN_COOLDOWN_MULTIPLIER"), 1)))
                    : tuning.integer(s("COOLDOWN_TICKS"), Config.uniqueEffects.stormbringer.chainLightningCooldown);
            if (tuning.flag(1 << 24)) {
                cooldown = resolvedChainCooldown(cooldown, damaged.size(),
                        integer(tuning, s("STORMBRINGER_CADENCE_REFUND_PER_TARGET"), s("REFUND_TICKS"), 4),
                        integer(tuning, s("STORMBRINGER_CADENCE_MIN_COOLDOWN_TICKS"),
                                s("COOLDOWN_TICKS"), 8));
            }
            state.nextChainTick = now + SimplySwordsAPI.getEffectiveWeaponCooldownTicks(stack, player, cooldown);
            markCombat(player);
            UniqueAbilityApi.emit(execution, UniqueAbilityPhase.HIT, StormFrostWaterMasteryAbilities.HIT,
                    target, damaged.size(), baseDamage);
        } finally {
            SUPPRESS_CHAIN.set(false);
            UniqueAbilityApi.finish(execution, StormFrostWaterMasteryAbilities.FINISH, 0);
        }
        }
    }

private static boolean damage(ServerWorld world, ServerPlayerEntity player, ItemStack stack,
                                  LivingEntity target, float damage, Set<UUID> killed) {
        boolean alive = target.isAlive();
        boolean result = ChainLightningVisualManager.damageBoltTarget(world, player, stack, target, damage);
        if (result && alive && !target.isAlive()) killed.add(target.getUuid());
        return result;
    }

private static void damageGroundCurrent(ServerWorld world, ServerPlayerEntity player, ItemStack stack,
                                            List<LivingEntity> chain, float baseDamage, StormFrostWaterMasteryTuning tuning,
                                            Set<UUID> damaged, Set<UUID> killed) {
        LivingEntity origin = chain.getLast();
        double radius = value(tuning, s("STORMBRINGER_BURST_RADIUS"), s("RADIUS"), 2);
        int cap = integer(tuning, s("STORMBRINGER_BURST_TARGET_CAP"), s("TARGET_CAP"), 6);
        Set<UUID> excluded = chain.stream().map(LivingEntity::getUuid)
                .collect(java.util.stream.Collectors.toSet());
        List<LivingEntity> targets = world.getEntitiesByClass(LivingEntity.class,
                        new Box(origin.getPos(), origin.getPos()).expand(radius), candidate ->
                                candidate != player && candidate.isAlive()
                                        && !excluded.contains(candidate.getUuid())
                                        && EntityPredicates.VALID_LIVING_ENTITY.test(candidate)
                                        && HelperMethods.checkAbilityTarget(candidate, player))
                .stream()
                .sorted(Comparator.comparing(LivingEntity::getUuid))
                .limit(Math.max(1, Config.uniqueEffects.stormbringer.chainSearchCap))
                .sorted(Comparator.comparingDouble((LivingEntity candidate) -> candidate.squaredDistanceTo(origin))
                        .thenComparing(LivingEntity::getUuid))
                .limit(cap)
                .toList();
        float damage = baseDamage * (float) value(tuning,
                s("STORMBRINGER_BURST_DAMAGE_MULTIPLIER"), s("SECONDARY_DAMAGE_MULTIPLIER"), .25);
        List<LivingEntity> visualHits = new ArrayList<>();
        for (LivingEntity candidate : targets) {
            if (damage(world, player, stack, candidate, damage, killed)) {
                damaged.add(candidate.getUuid());
                visualHits.add(candidate);
                applyMark(world, player, candidate, tuning);
            }
        }
        ChainLightningVisualManager.spawnStormbringerBurstEffects(world, origin, visualHits);
    }

private static OwnerState ownerState(ServerPlayerEntity player) {
        RegistryKey<World> world = player.getWorld().getRegistryKey();
        OwnerState state = OWNERS.computeIfAbsent(player.getUuid(), ignored -> new OwnerState(world));
        if (!state.world.equals(world)) {
            UUID owner = player.getUuid();
            MARKS.entrySet().removeIf(entry -> entry.getKey().owner.equals(owner));
            state.world = world;
            state.nextChainTick = Long.MIN_VALUE;
            state.nextFreeChainTick = Long.MIN_VALUE;
            state.nextOverflowTick = Long.MIN_VALUE;
            state.nextDecayTick = Long.MIN_VALUE;
            state.lastAttemptTick = Long.MIN_VALUE;
            state.spentAt.clear();
        }
        return state;
    }

private static void applyMark(ServerWorld world, ServerPlayerEntity owner, LivingEntity target,
                                  StormFrostWaterMasteryTuning tuning) {
        if (!tuning.flag(1 << 21) || !target.isAlive()) return;
        int duration = integer(tuning, s("STORMBRINGER_MARK_DURATION_TICKS"),
                s("STATUS_DURATION_TICKS"), 80);
        MARKS.put(new MarkKey(owner.getUuid(), target.getUuid()),
                new MarkState(world.getRegistryKey(), world.getTime() + duration));
    }

private static boolean isMarked(ServerWorld world, ServerPlayerEntity owner, LivingEntity target) {
        MarkKey key = new MarkKey(owner.getUuid(), target.getUuid());
        MarkState mark = MARKS.get(key);
        if (mark == null) return false;
        if (!mark.world.equals(world.getRegistryKey()) || world.getTime() >= mark.expiresAt) {
            MARKS.remove(key);
            return false;
        }
        return true;
    }

private static void recordSpentCharges(ServerPlayerEntity player, StormFrostWaterMasteryTuning tuning, int spent) {
        OwnerState state = ownerState(player);
        long now = player.getServerWorld().getTime();
        int window = integer(tuning, s("STORMBRINGER_RHYTHM_WINDOW_TICKS"), s("LOCKOUT_TICKS"), 100);
        int required = integer(tuning, s("STORMBRINGER_RHYTHM_SPEND_COUNT"), s("COUNT"), 3);
        while (!state.spentAt.isEmpty() && state.spentAt.peekFirst() < now - window) state.spentAt.removeFirst();
        for (int i = 0; i < spent; i++) state.spentAt.addLast(now);
        while (required > 0 && state.spentAt.size() >= required) {
            for (int i = 0; i < required; i++) state.spentAt.removeFirst();
            player.addStatusEffect(new StatusEffectInstance(StatusEffects.HASTE,
                    integer(tuning, s("STORMBRINGER_RHYTHM_HASTE_TICKS"),
                            s("STATUS_DURATION_TICKS"), 80), 0), player);
        }
    }

public static void tickPlayer(ServerPlayerEntity player) {
        MasteryAbsorptionTracker.tick(player);
        long now = player.getServerWorld().getTime();
        if (player.age % 20 == 0) {
            RegistryKey<World> key = player.getWorld().getRegistryKey();
            MARKS.entrySet().removeIf(entry -> entry.getValue().world.equals(key)
                    && now >= entry.getValue().expiresAt);
        }
        ItemStack stack = player.getMainHandStack().isOf(ItemsRegistry.STORMBRINGER.get())
                ? player.getMainHandStack() : player.getOffHandStack();
        if (!stack.isOf(ItemsRegistry.STORMBRINGER.get()) || !AwakeningApi.isAbilityUnlocked(stack)) return;
        ParryComponent component = stack.getOrDefault(ComponentTypeRegistry.PARRY.get(), ParryComponent.DEFAULT);
        if (component.stormCharges() <= 0) return;
        OwnerState state = ownerState(player);
        if (state.tuning == null || now >= state.nextTuningRefreshTick) {
            state.tuning = resolveChainTuning(player, stack, null);
            state.nextTuningRefreshTick = now + 20;
        }
        StormFrostWaterMasteryTuning tuning = state.tuning;
        int cap = chargeCap(tuning);
        component = normalizeCharges(stack, cap);
        if (!tuning.flag(1 << 16) || component.stormCharges() <= 0) return;
        int interval = integer(tuning, s("STORMBRINGER_SUPERCELL_DECAY_TICKS"),
                s("INTERVAL_TICKS"), 40);
        if (!shouldDecay(now, state.lastCombatTick, COMBAT_GRACE_TICKS)) {
            state.nextDecayTick = now + interval;
            return;
        }
        if (state.nextDecayTick == Long.MIN_VALUE) state.nextDecayTick = now + interval;
        while (component.stormCharges() > 0 && now >= state.nextDecayTick) {
            component = component.consumeStormCharge();
            state.nextDecayTick += interval;
        }
        stack.set(ComponentTypeRegistry.PARRY.get(), component);
    }

