private static void applyStrike(ServerWorld world, PendingStrike strike) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(strike == null ? null : CombatProvenanceApi.from(strike.stack(), null))) {
        Entity sourceEntity = world.getEntity(strike.sourceId);
        if (!(sourceEntity instanceof LivingEntity source) || !source.isAlive()) {
            if (strike.execution != null) UniqueAbilityApi.cancel(strike.execution);
            return;
        }

        boolean stillWind = strike.stillWind;
        boolean nearestOnly = strike.tuning.get(StormSoulMasteryTuning.Setting.STRIKE_NEAREST_ONLY, 0) >= 1;
        int targetCap = strike.tuning.has(StormSoulMasteryTuning.Setting.STRIKE_TARGET_CAP)
                ? strike.tuning.integer(StormSoulMasteryTuning.Setting.STRIKE_TARGET_CAP, 64) : Integer.MAX_VALUE;
        if (nearestOnly || stillWind) targetCap = 1;

        List<LivingEntity> targets = new ArrayList<>();
        for (UUID targetId : strike.targetIds) {
            if (world.getEntity(targetId) instanceof LivingEntity target && target.isAlive()
                    && HelperMethods.checkAbilityTarget(target, source)) {
                targets.add(target);
            }
        }
        targets.sort(Comparator.comparingDouble(target -> target.squaredDistanceTo(strike.end)));

        float multiplier = (float) strike.tuning.get(StormSoulMasteryTuning.Setting.STRIKE_DAMAGE_MULTIPLIER, 1);
        if (stillWind) {
            multiplier *= (float) strike.tuning.get(StormSoulMasteryTuning.Setting.STILL_WIND_MULTIPLIER, 1);
        }
        multiplier *= (float) (1.0 + arrangementBonus(strike, targets.size()));
        multiplier *= (float) (1.0 + WhisperwindRhythmManager.tempoBonus(world, source, strike.tuning));

        double perTargetBonus = strike.tuning.get(StormSoulMasteryTuning.Setting.BOUQUET_PER_TARGET_BONUS, 0);
        int bouquetCap = strike.tuning.integer(StormSoulMasteryTuning.Setting.BOUQUET_TARGET_CAP, 64);
        int scalingTargets = Math.min(targets.size(), bouquetCap);
        float damage = HelperMethods.abilityScaledDamage("evocation", source, strike.stack,
                Config.uniqueEffects.whisperwind.delayedDamageScaling
                        + scalingTargets * Config.uniqueEffects.whisperwind.delayedDamagePerTargetScaling
                        * (float) (1.0 + perTargetBonus),
                Config.uniqueEffects.whisperwind.delayedSpellScaling
                        + scalingTargets * Config.uniqueEffects.whisperwind.delayedSpellPerTargetScaling
                        * (float) (1.0 + perTargetBonus)) * multiplier;

        int hits = Math.max(1, strike.tuning.integer(StormSoulMasteryTuning.Setting.STRIKE_COUNT, 1));
        int affected = 0;
        int kills = 0;
        for (LivingEntity target : targets) {
            target.timeUntilRegen = 0;
            var damageSource = world.getDamageSources().indirectMagic(source, source);
            float resolved = applyArmorIgnore(target, strike.tuning, damage);
            boolean damaged = false;
            for (int hit = 0; hit < hits; hit++) {
                if (hit > 0) target.timeUntilRegen = 0;
                damaged |= CombatProvenanceApi.damage(strike.stack, (damageSource).getAttacker(), target, damageSource, HelperMethods.applyAbilityDamageEnchantments(
                        world, strike.stack, target, damageSource, resolved));
                if (!target.isAlive()) break;
            }
            if (damaged) {
                affected++;
                if (strike.tuning.integer(StormSoulMasteryTuning.Setting.WEAKNESS_DURATION_TICKS, 0) > 0) {
                    target.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(
                            net.minecraft.entity.effect.StatusEffects.WEAKNESS,
                            strike.tuning.integer(StormSoulMasteryTuning.Setting.WEAKNESS_DURATION_TICKS, 0), 0), source);
                }
                if (!target.isAlive()) {
                    kills++;
                    secondFlowering(world, source, strike, target, resolved);
                }
                if (strike.execution != null) UniqueAbilityApi.emit(strike.execution, UniqueAbilityPhase.HIT,
                        StormSoulMasteryAbilities.HIT, target, 1, resolved);
            }
            spawnBlossoms(world, target);
            if (affected >= targetCap) break;
        }
        if (kills > 0) WhisperwindRhythmManager.recordStrikeKill(world, source, strike.tuning);
        refundOnWideStrike(source, strike, affected);
        if (strike.execution != null) UniqueAbilityApi.finish(strike.execution, StormSoulMasteryAbilities.FINISH, affected);

        world.playSound(null, strike.end.x, strike.end.y, strike.end.z,
                SoundRegistry.ELEMENTAL_SWORD_WIND_ATTACK_03.get(),
                SoundCategory.PLAYERS, 0.75F, 1.25F + world.random.nextFloat() * 0.18F);
        spawnSlash(world, strike.start, strike.end);
        }
    }

private static void secondFlowering(ServerWorld world, LivingEntity source, PendingStrike strike,
                                        LivingEntity victim, float dealt) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(strike == null ? null : CombatProvenanceApi.from(strike.stack(), null))) {
        double multiplier = strike.tuning.get(StormSoulMasteryTuning.Setting.FLOWERING_MULTIPLIER, 0);
        double radius = strike.tuning.get(StormSoulMasteryTuning.Setting.FLOWERING_RADIUS, 0);
        if (multiplier <= 0 || radius <= 0 || dealt <= 0) return;
        int cap = Math.max(1, strike.tuning.integer(StormSoulMasteryTuning.Setting.FLOWERING_TARGET_CAP, 3));
        int splashed = 0;
        var damageSource = world.getDamageSources().indirectMagic(source, source);
        for (LivingEntity nearby : world.getEntitiesByClass(LivingEntity.class,
                victim.getBoundingBox().expand(radius),
                entity -> entity != source && entity != victim && entity.isAlive()
                        && EntityPredicates.VALID_LIVING_ENTITY.test(entity)
                        && HelperMethods.checkAbilityTarget(entity, source))) {
            nearby.timeUntilRegen = 0;
            CombatProvenanceApi.damage(strike.stack, (damageSource).getAttacker(), nearby, damageSource, HelperMethods.applyAbilityDamageEnchantments(
                    world, strike.stack, nearby, damageSource, (float) (dealt * multiplier)));
            if (++splashed >= cap) break;
        }
        }
    }

private static void refundOnWideStrike(LivingEntity source, PendingStrike strike, int affected) {
        int threshold = strike.tuning.integer(StormSoulMasteryTuning.Setting.RETURN_THRESHOLD, 0);
        int refund = strike.tuning.integer(StormSoulMasteryTuning.Setting.RETURN_REFUND_TICKS, 0);
        if (threshold <= 0 || refund <= 0 || affected < threshold) return;
        net.sweenus.simplyswords.api.SimplySwordsAPI.reduceWeaponCooldown(source, strike.stack,
                Config.uniqueEffects.whisperwind.cooldown, refund);
    }

public static void clear(ServerWorld world) {
        Map<UUID, ActiveDash> dashes = ACTIVE_DASHES.remove(world);
        if (dashes != null) {
            for (ActiveDash dash : dashes.values()) {
                if (dash.execution != null) UniqueAbilityApi.cancel(dash.execution);
            }
        }
        Set<PendingStrike> strikes = PENDING_STRIKES.remove(world);
        if (strikes != null) {
            for (PendingStrike strike : strikes) {
                if (strike.execution != null) UniqueAbilityApi.cancel(strike.execution);
            }
        }
    }

public static void clearAll() {
        for (Map<UUID, ActiveDash> dashes : ACTIVE_DASHES.values()) {
            for (ActiveDash dash : dashes.values()) {
                if (dash.execution != null) UniqueAbilityApi.cancel(dash.execution);
            }
        }
        for (Set<PendingStrike> strikes : PENDING_STRIKES.values()) {
            for (PendingStrike strike : strikes) {
                if (strike.execution != null) UniqueAbilityApi.cancel(strike.execution);
            }
        }
        ACTIVE_DASHES.clear();
        PENDING_STRIKES.clear();
    }

public static int resolveChance(ServerWorld world, LivingEntity owner, StormSoulMasteryTuning tuning,
                                    int baseChance) {
        RhythmState state = state(world, owner.getUuid());
        long now = world.getTime();
        int repriseWindow = tuning.integer(StormSoulMasteryTuning.Setting.REPRISE_WINDOW_TICKS, 0);
        if (repriseWindow > 0 && state.repriseUntil >= now) {
            state.repriseUntil = Long.MIN_VALUE;
            return 100;
        }
        double perFailure = tuning.get(StormSoulMasteryTuning.Setting.RHYTHM_CHANCE_PER_FAILURE, 0);
        if (perFailure <= 0) return baseChance;
        int window = tuning.integer(StormSoulMasteryTuning.Setting.RHYTHM_WINDOW_TICKS, 100);
        if (state.failuresExpire < now) state.failures = 0;
        state.failuresExpire = now + window;
        double cap = tuning.get(StormSoulMasteryTuning.Setting.RHYTHM_CHANCE_CAP, 0);
        return baseChance + (int) Math.min(cap, state.failures * perFailure);
    }

public static void recordRefreshResult(ServerWorld world, LivingEntity owner, boolean refreshed) {
        RhythmState state = state(world, owner.getUuid());
        if (refreshed) {
            state.failures = 0;
        } else {
            state.failures++;
        }
    }

public static boolean recordStillWindAttack(ServerWorld world, LivingEntity owner,
                                                StormSoulMasteryTuning tuning) {
        int threshold = tuning.integer(StormSoulMasteryTuning.Setting.STILL_WIND_THRESHOLD, 0);
        if (threshold <= 0) return false;
        RhythmState state = state(world, owner.getUuid());
        long now = world.getTime();
        int window = Math.max(1, tuning.integer(StormSoulMasteryTuning.Setting.STILL_WIND_WINDOW_TICKS, 80));
        if (state.attacksExpire < now) state.attacks = 0;
        state.attacksExpire = now + window;
        state.attacks++;
        if (state.attacks < threshold) return false;
        state.attacks = 0;
        return true;
    }

public static boolean tryPartialRefresh(ServerWorld world, LivingEntity owner, ItemStack stack,
                                            StormSoulMasteryTuning tuning, int totalCooldownTicks) {
        try (var masteryProvenanceScope = CombatProvenanceApi.scope(CombatProvenanceApi.from(stack, null))) {
        int refund = tuning.integer(StormSoulMasteryTuning.Setting.REFRESH_REFUND_TICKS, 0);
        if (refund <= 0) return false;
        RhythmState state = state(world, owner.getUuid());
        long now = world.getTime();
        int interval = Math.max(1, tuning.integer(StormSoulMasteryTuning.Setting.REFRESH_INTERVAL_TICKS, 20));
        if (now < state.refreshReady) return true;
        state.refreshReady = now + interval;
        net.sweenus.simplyswords.api.SimplySwordsAPI.reduceWeaponCooldown(owner, stack,
                totalCooldownTicks, refund);
        int speedTicks = tuning.integer(StormSoulMasteryTuning.Setting.REFRESH_SPEED_TICKS, 0);
        if (speedTicks > 0) {
            owner.addStatusEffect(new StatusEffectInstance(StatusEffects.SPEED, speedTicks,
                    Math.max(0, tuning.integer(StormSoulMasteryTuning.Setting.REFRESH_SPEED_AMPLIFIER, 1)),
                    false, true, true), owner);
        }
        return true;
        }
    }

public static void recordRefresh(ServerWorld world, LivingEntity owner) {
        state(world, owner.getUuid()).lastRefresh = world.getTime();
    }

public static double tempoBonus(ServerWorld world, LivingEntity owner, StormSoulMasteryTuning tuning) {
        double bonus = tuning.get(StormSoulMasteryTuning.Setting.TEMPO_DAMAGE_BONUS, 0);
        int window = tuning.integer(StormSoulMasteryTuning.Setting.TEMPO_WINDOW_TICKS, 0);
        if (bonus <= 0 || window <= 0) return 0;
        RhythmState state = state(world, owner.getUuid());
        if (world.getTime() - state.lastRefresh > window) return 0;
        int hasteTicks = tuning.integer(StormSoulMasteryTuning.Setting.TEMPO_HASTE_TICKS, 0);
        if (hasteTicks > 0) {
            owner.addStatusEffect(new StatusEffectInstance(StatusEffects.HASTE, hasteTicks, 0,
                    false, true, true), owner);
        }
        return bonus;
    }

public static void recordStrikeKill(ServerWorld world, LivingEntity owner, StormSoulMasteryTuning tuning) {
        int window = tuning.integer(StormSoulMasteryTuning.Setting.REPRISE_WINDOW_TICKS, 0);
        if (window <= 0) return;
        state(world, owner.getUuid()).repriseUntil = world.getTime() + window;
    }

@Override
    public boolean postHit(ItemStack stack, LivingEntity target, LivingEntity attacker) {
        if (!net.sweenus.simplyswords.api.AwakeningApi.isAbilityUnlocked(stack)) {
            return super.postHit(stack, target, attacker);
        }
        HelperMethods.playHitSounds(attacker, target);
        if (attacker.getWorld() instanceof ServerWorld world) {
            UniqueAbilityExecution execution = UniqueAbilityApi.preparePassive(StormSoulMasteryAbilities.WHISPERWIND_RESET,
                    UniqueAbilityContext.passive(world, stack, attacker, target, null), builder -> builder
                            .set(StormSoulMasteryAbilities.TUNING, StormSoulMasteryTuning.EMPTY));
            UniqueAbilityApi.start(execution);
            StormSoulMasteryTuning tuning = StormSoulMasteryAbilities.tuning(execution);
            boolean stillWind = tuning.integer(StormSoulMasteryTuning.Setting.STILL_WIND_THRESHOLD, 0) > 0;
            if (stillWind) {
                if (WhisperwindRhythmManager.recordStillWindAttack(world, attacker, tuning)
                        && target.isAlive() && HelperMethods.checkAbilityTarget(target, attacker)) {
                    UniqueAbilityExecution stillWindExecution = UniqueAbilityApi.preparePassive(
                            StormSoulMasteryAbilities.WHISPERWIND_STILL_WIND,
                            UniqueAbilityContext.passive(world, stack, attacker, target, null), builder -> builder
                                    .set(StormSoulMasteryAbilities.TUNING, StormSoulMasteryTuning.EMPTY));
                    UniqueAbilityApi.start(stillWindExecution);
                    WhisperwindVisualManager.scheduleStillWindStrike(world, attacker, target, stack,
                            stillWindExecution, StormSoulMasteryAbilities.tuning(stillWindExecution));
                }
            } else {
                int chance = WhisperwindRhythmManager.resolveChance(world, attacker, tuning,
                        tuning.integer(StormSoulMasteryTuning.Setting.CHANCE, Config.uniqueEffects.whisperwind.chance));
                int resetRoll = attacker.getRandom().nextInt(100);
                boolean reset = tuning.has(StormSoulMasteryTuning.Setting.CHANCE)
                        ? chance >= 100 || chance > 0 && resetRoll < chance
                        : resetRoll <= chance;
                UniqueAbilityApi.reportRoll(attacker, StormSoulMasteryAbilities.WHISPERWIND_RESET.id(),
                        "CHANCE", chance, resetRoll, reset);
                WhisperwindRhythmManager.recordRefreshResult(world, attacker, reset);
                if (reset && attacker instanceof PlayerEntity player) {
                    attacker.getWorld().playSoundFromEntity(null, attacker, SoundRegistry.MAGIC_SWORD_SPELL_02.get(),
                            attacker.getSoundCategory(), 0.3f, 1.8f);
                    if (!WhisperwindRhythmManager.tryPartialRefresh(world, player, stack, tuning,
                            Config.uniqueEffects.whisperwind.cooldown)) {
                        SimplySwordsAPI.setWeaponCooldown(player, stack, 0);
                    }
                    WhisperwindRhythmManager.recordRefresh(world, player);
                    UniqueAbilityApi.emit(execution, UniqueAbilityPhase.HIT, StormSoulMasteryAbilities.HIT,
                            target, 1, chance);
                }
            }
            UniqueAbilityApi.finish(execution, StormSoulMasteryAbilities.FINISH, 1);
        }
        return super.postHit(stack, target, attacker);
    }

@Override
    public TypedActionResult<ItemStack> startPlayerAbility(World world, PlayerEntity user, Hand hand) {
        ItemStack stack = user.getStackInHand(hand);
        world.playSoundFromEntity(null, user, SoundRegistry.ELEMENTAL_BOW_SCIFI_SHOOT_IMPACT_01.get(),
                user.getSoundCategory(), 0.6f, 1.0f);
        StormSoulMasteryTuning playerTuning = StormSoulMasteryTuning.EMPTY;
        if (!world.isClient() && world instanceof ServerWorld serverWorld) {
            UniqueAbilityExecution execution = UniqueAbilityApi.preparePassive(StormSoulMasteryAbilities.WHISPERWIND_DASH,
                    UniqueAbilityContext.passive(serverWorld, stack, user, null, hand), builder -> builder
                            .set(StormSoulMasteryAbilities.TUNING, StormSoulMasteryTuning.EMPTY)
                            .set(StormSoulMasteryAbilities.COOLDOWN_TICKS, Config.uniqueEffects.whisperwind.cooldown));
            UniqueAbilityApi.start(execution);
            StormSoulMasteryTuning tuning = StormSoulMasteryAbilities.tuning(execution);
            playerTuning = tuning;
            WhisperwindVisualManager.startDash(serverWorld, user, stack, execution, tuning);
            WhisperwindRhythmManager.startWindbreak(serverWorld, user, tuning);
            SimplySwordsAPI.setWeaponCooldown(user, stack, execution.cooldownTicks(Config.uniqueEffects.whisperwind.cooldown));
        }
        user.addStatusEffect(new StatusEffectInstance(EffectRegistry.getReference(EffectRegistry.FATAL_FLICKER),
                playerTuning.integer(StormSoulMasteryTuning.Setting.DASH_TICKS, 12)));
        user.addStatusEffect(new StatusEffectInstance(StatusEffects.ABSORPTION,
                playerTuning.integer(StormSoulMasteryTuning.Setting.DASH_ABSORPTION_TICKS, 100),
                playerTuning.integer(StormSoulMasteryTuning.Setting.DASH_ABSORPTION, 2) >= 4 ? 1 : 0));

        return super.use(world, user, hand);
    }

@Override
